<?php require_once __DIR__.'/../functions.php';if(!admin())redirect('../login.php');if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['id'];$status=$_POST['status'];$pay=$_POST['payment_status'];$s=db()->prepare('UPDATE bookings SET status=?,payment_status=? WHERE id=?');$s->execute([$status,$pay,$id]);flash('Booking updated.');redirect('bookings.php');}$rows=db()->query('SELECT b.*,r.name room_name FROM bookings b JOIN rooms r ON r.id=b.room_id ORDER BY b.created_at DESC')->fetchAll();header_html('Manage Bookings');?><main class="container py-5"><h1>Bookings</h1><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>Guest</th><th>Room</th><th>Dates</th><th>Total</th><th>Status</th><th>Payment</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['guest_name'])?></b><br><?=e($r['phone'])?></td><td><?=e($r['room_name'])?></td><td><?=e($r['check_in'])?> → <?=e($r['check_out'])?></td><td>TZS <?=number_format($r['total'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-select form-select-sm"><option <?=$r['status']=='pending'?'selected':''?>>pending</option><option <?=$r['status']=='confirmed'?'selected':''?>>confirmed</option><option <?=$r['status']=='cancelled'?'selected':''?>>cancelled</option><option <?=$r['status']=='completed'?'selected':''?>>completed</option></select></td><td><select name="payment_status" class="form-select form-select-sm"><option <?=$r['payment_status']=='unpaid'?'selected':''?>>unpaid</option><option <?=$r['payment_status']=='pending'?'selected':''?>>pending</option><option <?=$r['payment_status']=='paid'?'selected':''?>>paid</option></select></td><td><button class="btn btn-sm btn-gold">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></main><?php footer_html();?>